	var referenced bool
	if err := db.WithContext(ctx).Raw(genreDeleteReferencedSQL, key).Scan(&referenced).Error; err != nil {
		return repox.MapGormErr(err)
	}
	if referenced {
		return repox.ReferencedByRow("catalog.example.com/Genre", name)
	}
	return nil
