// Update persists the masked fields of in; an empty mask replaces every
// mutable field. The write happens in one transaction guarded by in.Etag.
func (r *GormShelfRepository) Update(ctx context.Context, in *catalogv1.Shelf, paths []string) (*catalogv1.Shelf, error) {
	key, err := r.rowKey(in.GetName())
	if err != nil {
		return nil, err
	}
	err = r.DB.Transaction(func(tx *gorm.DB) error { return r.updateTx(ctx, tx, key, in, paths, nil) })
	if err != nil {
		return nil, repox.MapGormErr(err)
	}
	return r.get(ctx, key)
}

// UpdateWithOutputOnly is Update plus the server-owned fields outputPaths
// names, in Update's transaction and under its etag guard.
func (r *GormShelfRepository) UpdateWithOutputOnly(ctx context.Context, in *catalogv1.Shelf, paths, outputPaths []string) (*catalogv1.Shelf, error) {
	key, err := r.rowKey(in.GetName())
	if err != nil {
		return nil, err
	}
	err = r.DB.Transaction(func(tx *gorm.DB) error { return r.updateTx(ctx, tx, key, in, paths, outputPaths) })
	if err != nil {
		return nil, repox.MapGormErr(err)
	}
	return r.get(ctx, key)
}

// updateTx is Update's write inside tx, which a Batch shares with other
// writes. The row is read FOR UPDATE: a concurrent update of the same record
// waits for this transaction and then sees the etag it wrote, so two writers
// holding the same etag cannot both pass the guard. outputPaths names the
// server-owned fields written alongside (UpdateWithOutputOnly); nil for Update.
func (r *GormShelfRepository) updateTx(ctx context.Context, tx *gorm.DB, key string, in *catalogv1.Shelf, paths, outputPaths []string) error {
	var existing catalog.Shelf
	if err := tx.WithContext(ctx).Clauses(clause.Locking{Strength: "UPDATE"}).First(&existing, "id = ?", key).Error; err != nil {
		return err
	}
	id := existing.ID
	_ = id
	if in.GetEtag() != "" && existing.Etag != nil && *existing.Etag != in.GetEtag() {
		return repox.ErrConflict
	}
	existingPB := catalog.ShelfToProto(&existing)
	joined, err := r.readJoins(ctx, tx, nil, id)
	if err != nil {
		return err
	}
	existingPB.Featured = joined["featured"][id]
	merged := proto.Clone(existingPB).(*catalogv1.Shelf)
	applyShelfMask(merged, in, paths)
	repox.CopyFields(merged, in, outputPaths)
	if h := r.Hooks.BeforeUpdate; h != nil {
		if err := h(ctx, existingPB, merged, paths); err != nil {
			return err
		}
	}
	next := catalog.ShelfFromProto(merged)
	_ = next
	existing.Name = next.Name
	existing.DisplayName = next.DisplayName
	if len(outputPaths) > 0 {
		paths := outputPaths
		if repox.InMask(paths, "expire_time") {
			existing.ExpireTime = next.ExpireTime
		}
	}
	if repox.InMask(paths, "featured") {
		if err := shelfFeaturedJoin.Write(ctx, tx, id, merged.GetFeatured()); err != nil {
			return err
		}
	}
	existing.Etag = repox.Ptr(repox.NewULID())
	return r.store(tx).Update(ctx, &existing)
}

// UpdateOutputOnly persists the server-owned fields of in that paths names, in
// one transaction guarded by in.Etag.
func (r *GormShelfRepository) UpdateOutputOnly(ctx context.Context, in *catalogv1.Shelf, paths []string) (*catalogv1.Shelf, error) {
	key, err := r.rowKey(in.GetName())
	if err != nil {
		return nil, err
	}
	err = r.DB.Transaction(func(tx *gorm.DB) error { return r.updateOutputOnlyTx(ctx, tx, in, paths) })
	if err != nil {
		return nil, repox.MapGormErr(err)
	}
	return r.get(ctx, key)
}

// updateOutputOnlyTx is UpdateOutputOnly's write inside tx, which a Batch
// shares with other writes.
func (r *GormShelfRepository) updateOutputOnlyTx(ctx context.Context, tx *gorm.DB, in *catalogv1.Shelf, paths []string) error {
	if len(paths) == 0 {
		return fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument)
	}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		return err
	}
	{
		var existing catalog.Shelf
		// FOR UPDATE, as in updateTx: concurrent writers holding one etag
		// take turns, and only the first passes the guard.
		if err := tx.WithContext(ctx).Clauses(clause.Locking{Strength: "UPDATE"}).First(&existing, "id = ?", key).Error; err != nil {
			return err
		}
		if in.GetEtag() != "" && existing.Etag != nil && *existing.Etag != in.GetEtag() {
			return repox.ErrConflict
		}
		next := catalog.ShelfFromProto(in)
		if repox.InMask(paths, "expire_time") {
			existing.ExpireTime = next.ExpireTime
		}
		existing.Etag = repox.Ptr(repox.NewULID())
		return r.store(tx).Update(ctx, &existing)
	}
}

// newRow builds the row a Batch inserts for in, and the
// record it stands for, named: the same resolution Create applies.
func (r *GormShelfRepository) newRow(in *catalogv1.Shelf) (*catalog.Shelf, *catalogv1.Shelf, error) {
	id := repox.NewULID()
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "shelves")
		if err != nil {
			return nil, nil, err
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*catalogv1.Shelf)
	in.Name = FormatShelfName(id)
	m := catalog.ShelfFromProto(in)
	m.ID = id
	m.Name = in.GetName()
	m.Etag = repox.Ptr(repox.NewULID())
	return m, in, nil
}

// insertTx writes m inside tx with the value-object rows in carries: those
// it points at first, then m, then its children and its join rows.
func (r *GormShelfRepository) insertTx(ctx context.Context, tx *gorm.DB, in *catalogv1.Shelf, m *catalog.Shelf) error {
	id := m.ID
	_ = id
	if err := r.store(tx).Create(ctx, m); err != nil {
		return err
	}
	if err := shelfFeaturedJoin.Write(ctx, tx, id, in.GetFeatured()); err != nil {
		return err
	}
	return nil
}

// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays.
func (r *GormShelfRepository) Delete(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	res := r.markDeleted(ctx, r.DB, key)
	if res.Error != nil {
		return repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		return repox.ErrNotFound
	}
	return nil
}

// markDeleted sets the soft-delete mark on the live row found by key
// (rowKey) through db: Delete's write, which a Batch runs inside its
// transaction.
func (r *GormShelfRepository) markDeleted(ctx context.Context, db *gorm.DB, key string) *gorm.DB {
	now := time.Now()
	return db.WithContext(ctx).Model(&catalog.Shelf{}).
		Where("id = ? AND delete_time IS NULL", key).
		Updates(map[string]any{"delete_time": now, "etag": repox.NewULID(), "expire_time": repox.ExpireAt(now, r.Retention)})
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GormShelfRepository) Undelete(ctx context.Context, name string) (*catalogv1.Shelf, error) {
	key, err := r.rowKey(name)
	if err != nil {
		return nil, err
	}
	res := r.DB.WithContext(ctx).Model(&catalog.Shelf{}).
		Where("id = ? AND delete_time IS NOT NULL", key).
		Updates(map[string]any{"delete_time": nil, "etag": repox.NewULID(), "expire_time": nil})
	if res.Error != nil {
		return nil, repox.MapGormErr(res.Error)
	}
	if res.RowsAffected == 0 {
		if _, err := r.get(ctx, key); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, key)
}

// Purge removes the record addressed by its resource name for good.
func (r *GormShelfRepository) Purge(ctx context.Context, name string) error {
	key, err := r.rowKey(name)
	if err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	_, err = r.purge(ctx, r.DB, key, name, true)
	return repox.MapGormErr(err)
}

// purge removes the row found by key (rowKey), named name, for good through
// db -- unless something
// still refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, then caught again from
// the constraint itself), or, when askReferrers, a referrer in another
// database or service (r.Refs). A purge never fails, and never cascades,
// because of a referrer. gorm.ErrRecordNotFound when there is no such row.
func (r *GormShelfRepository) purge(ctx context.Context, db *gorm.DB, key, name string, askReferrers bool) (kept bool, err error) {
	var referenced bool
	if err := db.WithContext(ctx).Raw(shelfReferencedSQL, key).Scan(&referenced).Error; err != nil {
		return false, err
	}
	if referenced {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	if askReferrers && r.Refs.KeepOnPurge(ctx, "catalog.example.com/Shelf", name) {
		return true, nil
	}
	// A savepoint inside a caller's transaction: a foreign key the query
	// above does not know (one from another generator run) rolls back only
	// this purge.
	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		var existing catalog.Shelf
		if err := tx.First(&existing, "id = ?", key).Error; err != nil {
			return err
		}
		return r.store(tx).DeleteByID(ctx, existing.ID)
	})
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// shelfReferencedSQL asks whether any row, deleted or not, still
// holds a foreign key to the Shelf row with the given key (rowKey).
const shelfReferencedSQL = `SELECT EXISTS (SELECT 1 FROM "catalog"."book_filed_under" r0 WHERE r0."shelf_id" = t."id") OR EXISTS (SELECT 1 FROM "catalog"."books" r1 WHERE r1."returns_to" = t."id") OR EXISTS (SELECT 1 FROM "catalog"."books" r2 WHERE r2."shelf_id" = t."id") OR EXISTS (SELECT 1 FROM "catalog"."pages" r3 WHERE r3."shelf_id" = t."id") FROM "catalog"."shelves" t WHERE t."id" = ?`

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GormShelfRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, r.DB, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			key, err := r.rowKey(m.GetName())
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, r.DB, key, m.GetName(), true)
			switch {
			case errors.Is(err, gorm.ErrRecordNotFound):
			case err != nil:
				return res, repox.MapGormErr(err)
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GormShelfRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*catalogv1.Shelf, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*catalogv1.Shelf, string, error) {
		return r.List(ctx, in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ ShelfRepository = (*GormShelfRepository)(nil)

// gormBatch is Batch on GORM: queued writes run in the Unit's transaction on
// Commit.
type gormBatch struct {
	u         *repox.Unit
	db        *gorm.DB
	stores    storeFuncs
	retention time.Duration
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *gormBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// CreateBook queues a create and returns the name the record will have.
func (b *gormBatch) CreateBook(parent string, in *catalogv1.Book) (string, error) {
	r := &GormBookRepository{DB: b.db, Store: b.stores.book}
	m, named, err := r.newRow(parent, in)
	if err != nil {
		return "", err
	}
	var locks []string
	if k, ok := any(m).(interface{ NoOverlapKeys() []string }); ok {
		locks = k.NoOverlapKeys()
	}
	queueBookReferences(b.u, named, nil)
	b.u.QueueGorm(locks, func(ctx context.Context, tx *gorm.DB) error {
		return r.insertTx(ctx, tx, named, m)
	})
	b.u.Record(repox.Change{Type: "catalog.example.com/Book", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateBook queues Update; in.Etag, when set, guards it, and a guard
// that fails rolls the whole batch back.
func (b *gormBatch) UpdateBook(in *catalogv1.Book, paths []string) {
	r := &GormBookRepository{DB: b.db, Store: b.stores.book}
	key, err := r.rowKey(in.GetName())
	if err != nil {
		b.u.Fail(err)
		return
	}
	queueBookReferences(b.u, in, paths)
	b.u.QueueGorm(nil, func(ctx context.Context, tx *gorm.DB) error {
		return r.updateTx(ctx, tx, key, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "catalog.example.com/Book", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getBook)})
}

